-- Migration: Year 3 - Psychiatry - Anxiety Disorders MCQ Bank (1-350)
-- Based on Kaplan & Sadock's Synopsis 12th Ed, First Aid for the Psychiatry Clerkship 5th Ed, and MGH Pocket Psychiatry
-- Date: 2026-04-30

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'anxiety-disorders' LIMIT 1;

    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Panic Disorder & Agoraphobia (1-70)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the defining feature of Panic Disorder?', '["Constant worry about daily events", "Recurrent, unexpected panic attacks with subsequent anticipatory anxiety", "Fear of social situations", "Fear of leaving home"]', 1, 'Must have unexpected attacks followed by 1+ month of worry about having another. (DSM-5)'),
    (v_topic_id, '2: How long does a typical panic attack take to peak?', '["Within seconds", "Within 10 minutes", "Within 1 hour", "Within 24 hours"]', 1, 'Abrupt surge of intense fear that peaks within 10 minutes. (First Aid)'),
    (v_topic_id, '3: Which of the following is NOT a somatic symptom of a panic attack?', '["Palpitations", "Sweating", "Bradycardia", "Shortness of breath"]', 2, 'Tachycardia, not bradycardia, is a hallmark of sympathetic overdrive. (Kaplan & Sadock)'),
    (v_topic_id, '4: To diagnose a panic attack, how many symptoms (e.g., palpitations, sweating, trembling, fear of dying) must be present?', '["At least 2", "At least 4", "At least 6", "All 13"]', 1, 'Requires 4 or more out of 13 possible symptoms. (DSM-5)'),
    (v_topic_id, '5: What is the primary fear in Agoraphobia?', '["Fear of spiders", "Fear of places or situations from which escape might be difficult or help unavailable in the event of panic", "Fear of public speaking", "Fear of the dark"]', 1, 'Often, but not always, co-occurs with Panic Disorder. (MGH Pocket)'),
    (v_topic_id, '6: To diagnose Agoraphobia, the fear/avoidance must last for at least:', '["1 month", "3 months", "6 months", "1 year"]', 2, 'Duration criterion is 6+ months for adults. (DSM-5)'),
    (v_topic_id, '7: First-line maintenance treatment for Panic Disorder?', '["Alprazolam", "SSRIs (e.g., Sertraline, Fluoxetine)", "Buspirone", "Haloperidol"]', 1, 'SSRIs/SNRIs are the foundation of long-term treatment. (First Aid)'),
    (v_topic_id, '8: Which medication is appropriate for aborting an ACUTE panic attack?', '["Fluoxetine", "Lithium", "Short-acting Benzodiazepines (e.g., Alprazolam, Lorazepam)", "Buspirone"]', 2, 'Used short-term while waiting for SSRI to take effect. (Kaplan & Sadock)'),
    (v_topic_id, '9: What is the risk of using Alprazolam long-term for Panic Disorder?', '["Schizophrenia", "Tolerance, dependence, and severe withdrawal symptoms (seizures)", "Permanent memory loss", "None"]', 1, 'Short half-life benzos carry the highest risk of withdrawal. (MGH Pocket)'),
    (v_topic_id, '10: Which non-pharmacological therapy is highly effective for Panic Disorder?', '["Psychoanalysis", "Cognitive Behavioral Therapy (CBT)", "ECT", "Light therapy"]', 1, 'CBT is as effective as medication and has longer-lasting benefits. (First Aid)'),
    (v_topic_id, '11: What specific CBT technique is used to recreate panic symptoms in a safe environment?', '["Flooding", "Interoceptive exposure", "Systematic desensitization", "Aversion therapy"]', 1, 'e.g., spinning in a chair to induce dizziness. (Kaplan & Sadock)'),
    (v_topic_id, '12: A patient presents to the ER with chest pain, palpitations, and fear of dying. ECG and troponins are normal. What must you rule out before diagnosing Panic Disorder?', '["Pheochromocytoma, Hyperthyroidism, Arrhythmias", "Schizophrenia", "Bipolar disorder", "None"]', 0, 'Medical causes must always be ruled out first. (First Aid)'),
    (v_topic_id, '13: Which substance withdrawal commonly mimics a panic attack?', '["Cocaine withdrawal", "Heroin withdrawal", "Alcohol or Benzodiazepine withdrawal", "Cannabis withdrawal"]', 2, 'Withdrawal from CNS depressants causes severe sympathetic overdrive. (MGH Pocket)'),
    (v_topic_id, '14: Which substance intoxication commonly mimics a panic attack?', '["Alcohol", "Cocaine, Amphetamines, or Caffeine", "Heroin", "None"]', 1, 'Stimulant intoxication causes tachycardia, diaphoresis, and anxiety. (Kaplan & Sadock)'),
    (v_topic_id, '15: Is Panic Disorder more common in men or women?', '["Men", "Women (2-3x more common)", "Equal", "None"]', 1, 'Most anxiety disorders have a female predominance. (First Aid)'),
    (v_topic_id, '16: Which genetic factor increases the risk of Panic Disorder?', '["First-degree relative with Panic Disorder (up to 8x higher risk)", "No genetic link", "Only identical twins", "None"]', 0, 'Strong familial aggregation. (Kaplan & Sadock)'),
    (v_topic_id, '17: What respiratory abnormality is theorized to play a role in Panic Disorder?', '["Hypoxia sensitivity", "Carbon dioxide (CO2) hypersensitivity (false suffocation alarm)", "Asthma", "None"]', 1, 'Infusion of sodium lactate or CO2 inhalation easily triggers panic in these patients. (MGH Pocket)'),
    (v_topic_id, '18: A patient with Agoraphobia typically avoids which of the following?', '["Public speaking", "Using public transportation, being in open spaces, or being in enclosed spaces (like a theater)", "Talking to strangers", "Spiders"]', 1, 'Avoids situations where escape is difficult. (DSM-5)'),
    (v_topic_id, '19: Can a patient be diagnosed with Agoraphobia WITHOUT having Panic Disorder?', '["Yes, they are separate diagnoses in DSM-5", "No, they must occur together", "Only in children", "None"]', 0, 'DSM-5 decoupled the two. (First Aid)'),
    (v_topic_id, '20: What is the recommended starting dose of SSRIs for Panic Disorder compared to Major Depressive Disorder (MDD)?', '["Double the MDD dose", "The same as MDD", "Start at half or one-quarter the typical MDD dose to avoid initial activation/worsening anxiety", "Do not use SSRIs"]', 2, '"Start low, go slow." (Kaplan & Sadock)'),
    (v_topic_id, '21: Which tricyclic antidepressant (TCA) was historically considered the gold standard for Panic Disorder before SSRIs?', '["Amitriptyline", "Clomipramine", "Imipramine", "Nortriptyline"]', 2, 'Imipramine is highly effective but limited by side effects. (MGH Pocket)'),
    (v_topic_id, '22: Are beta-blockers (like propranolol) effective for the core psychological fear in Panic Disorder?', '["Yes, first line", "No, they only mask peripheral autonomic symptoms (e.g., tachycardia) but do not stop the panic", "Yes, they cure it", "None"]', 1, 'Not recommended as monotherapy for panic disorder. (First Aid)'),
    (v_topic_id, '23: If a patient has panic attacks ONLY when exposed to dogs, what is the diagnosis?', '["Panic Disorder", "Specific Phobia", "Agoraphobia", "GAD"]', 1, 'Panic attacks in Specific Phobia are EXPECTED (cued), whereas in Panic Disorder they are UNEXPECTED. (Kaplan & Sadock)'),
    (v_topic_id, '24: A patient has panic attacks ONLY when reminded of a severe car accident they were in. Diagnosis?', '["Panic Disorder", "PTSD", "Specific Phobia", "Agoraphobia"]', 1, 'The panic is cued by trauma reminders. (MGH Pocket)'),
    (v_topic_id, '25: What is the role of the amygdala in Panic Disorder?', '["Decreased activity", "Hyperactive fear circuitry", "Shrunken size", "None"]', 1, 'The amygdala is the center of the fear response. (First Aid)'),
    (v_topic_id, '26: Which neurotransmitters are primarily implicated in Panic Disorder?', '["Dopamine only", "Serotonin, Norepinephrine, and GABA", "Acetylcholine only", "Glutamate only"]', 1, 'SSRIs, SNRIs, and Benzos target these. (Kaplan & Sadock)'),
    (v_topic_id, '27: What is "anticipatory anxiety"?', '["Fear of the future", "Persistent worry about having another panic attack", "Fear of social evaluation", "None"]', 1, 'A required criterion for Panic Disorder. (DSM-5)'),
    (v_topic_id, '28: What is "derepersonalization" during a panic attack?', '["Feeling like one''s surroundings are unreal", "Feeling detached from oneself or one''s body", "Passing out", "None"]', 1, 'A common dissociative symptom during severe panic. (First Aid)'),
    (v_topic_id, '29: What is "derealization" during a panic attack?', '["Feeling detached from oneself", "Feeling that the external world is unreal or distorted", "Hallucinating", "None"]', 1, 'Another dissociative symptom. (MGH Pocket)'),
    (v_topic_id, '30: What is the risk of suicide in Panic Disorder compared to the general population?', '["Lower", "The same", "Significantly elevated, especially if comorbid with MDD or substance abuse", "None"]', 2, 'Anxiety disorders carry significant morbidity. (Kaplan & Sadock)'),
    (v_topic_id, '31: A 25yo female presents with sudden onset palpitations, shortness of breath, and tingling in her lips and fingers. She is hyperventilating. What does the tingling represent?', '["Stroke", "Hypocalcemia due to respiratory alkalosis from hyperventilation", "Diabetic neuropathy", "None"]', 1, 'Hyperventilation -> low pCO2 -> elevated pH -> ionized calcium binds to albumin -> carpopedal spasm/tingling. (First Aid)'),
    (v_topic_id, '32: Best immediate non-pharmacological management for hyperventilation in a panic attack?', '["Breathe into a paper bag (rebreathing CO2)", "Oxygen mask", "CPR", "None"]', 0, 'Restores pCO2 levels and reverses respiratory alkalosis. (MGH Pocket)'),
    (v_topic_id, '33: Agoraphobia requires fear/avoidance of how many of the 5 defined situations (e.g., public transit, open spaces, enclosed spaces, lines/crowds, outside home alone)?', '["At least 1", "At least 2", "At least 3", "All 5"]', 1, 'Must fear 2 or more to distinguish from Specific Phobia. (DSM-5)'),
    (v_topic_id, '34: What is the most effective psychotherapy for Agoraphobia?', '["Psychoanalysis", "CBT with graded in vivo exposure", "Hypnosis", "Supportive therapy"]', 1, 'Exposure to the feared situations is critical. (Kaplan & Sadock)'),
    (v_topic_id, '35: Do patients with Panic Disorder retain insight during the attack?', '["Always", "Often they truly believe they are dying or having a heart attack despite previous negative workups", "Never", "None"]', 1, 'The physical sensations overwhelm logic. (First Aid)'),
    (v_topic_id, '36: What medical condition commonly mimics Panic Disorder and presents with flushing, diarrhea, and wheezing?', '["Pheochromocytoma", "Carcinoid syndrome", "Asthma", "Hyperthyroidism"]', 1, 'Due to serotonin excess. (MGH Pocket)'),
    (v_topic_id, '37: Which medical condition presents with episodic hypertension, headaches, sweating, and panic-like anxiety?', '["Pheochromocytoma", "Carcinoid syndrome", "Hypoglycemia", "None"]', 0, 'Due to catecholamine surges. (Kaplan & Sadock)'),
    (v_topic_id, '38: How does Paroxysmal Supraventricular Tachycardia (PSVT) differ clinically from a panic attack?', '["PSVT has abrupt onset and offset with heart rates often >150 bpm; Panic tachycardia is usually sinus and rarely >140 bpm", "They are identical", "Panic is faster", "None"]', 0, 'Holter monitor is useful to differentiate. (First Aid)'),
    (v_topic_id, '39: A patient abruptly stops their daily Paroxetine. They develop severe anxiety, electric shock sensations (brain zaps), and dizziness. Diagnosis?', '["Panic Disorder relapse", "SSRI Discontinuation Syndrome", "Serotonin Syndrome", "Stroke"]', 1, 'Paroxetine has a very short half-life; must taper slowly. (MGH Pocket)'),
    (v_topic_id, '40: Which SSRI is FDA approved for Panic Disorder and has the longest half-life (lowest risk of discontinuation syndrome)?', '["Paroxetine", "Sertraline", "Fluoxetine", "Citalopram"]', 2, 'Fluoxetine self-tapers. (Kaplan & Sadock)'),
    (v_topic_id, '41: Can SNRIs (like Venlafaxine) be used for Panic Disorder?', '["No", "Yes, they are FDA approved and considered first-line alongside SSRIs", "Only for depression", "None"]', 1, 'Effective for panic, though initial noradrenergic activation can temporarily worsen anxiety. (First Aid)'),
    (v_topic_id, '42: What is "nocturnal panic"?', '["Nightmares", "Waking from sleep in a state of panic (not triggered by a dream)", "Sleepwalking", "None"]', 1, 'Occurs in up to 70% of patients with panic disorder; usually during transition to stage 2 or 3 sleep. (MGH Pocket)'),
    (v_topic_id, '43: How does sleep terror differ from nocturnal panic?', '["Sleep terror has full memory", "Sleep terror involves amnesia for the event and typically occurs in children; nocturnal panic patients wake up fully and remember it", "They are the same", "None"]', 1, 'Crucial distinction. (Kaplan & Sadock)'),
    (v_topic_id, '44: Which brain structure is responsible for the somatic/autonomic symptoms of panic?', '["Prefrontal cortex", "Locus coeruleus (major source of norepinephrine)", "Hippocampus", "Cerebellum"]', 1, 'Stimulation of the locus coeruleus triggers panic. (First Aid)'),
    (v_topic_id, '45: A patient with Panic Disorder is prescribed a short course of Clonazepam while waiting for Sertraline to work. Why Clonazepam over Alprazolam?', '["Clonazepam is stronger", "Clonazepam has a longer half-life, providing smoother coverage and less inter-dose rebound anxiety", "Clonazepam is an SSRI", "None"]', 1, 'Alprazolam requires frequent dosing. (MGH Pocket)'),
    (v_topic_id, '46: In Panic Disorder, what is the role of the prefrontal cortex?', '["It initiates panic", "It fails to properly inhibit the overactive amygdala", "It causes sweating", "None"]', 1, 'CBT aims to strengthen top-down cortical control. (Kaplan & Sadock)'),
    (v_topic_id, '47: A patient fears leaving home because they might have a panic attack and pass out in public. This is a classic example of:', '["Specific Phobia", "Agoraphobia", "Social Anxiety Disorder", "Avoidant PD"]', 1, 'Fear of being trapped/helpless during panic. (First Aid)'),
    (v_topic_id, '48: If a patient refuses to take the elevator because they fear the elevator cable will snap, is this Agoraphobia?', '["Yes", "No, this is a Specific Phobia (Situational type)", "It is OCD", "None"]', 1, 'Agoraphobia focuses on the fear of panic/helplessness, whereas specific phobia focuses on harm from the object itself. (MGH Pocket)'),
    (v_topic_id, '49: How long should an SSRI trial last at a therapeutic dose before declaring it ineffective for Panic Disorder?', '["1 week", "2-3 weeks", "4-6 weeks (sometimes up to 8-12 weeks for full effect)", "6 months"]', 2, 'Anxiety disorders often require longer trials than MDD. (Kaplan & Sadock)'),
    (v_topic_id, '50: What is the typical duration of maintenance SSRI therapy for Panic Disorder after remission is achieved?', '["Stop immediately", "1-2 months", "12-24 months to prevent relapse", "Lifetime for everyone"]', 2, 'Premature discontinuation leads to high relapse rates. (First Aid)'),
    (v_topic_id, '51: If an SSRI and SNRI both fail for Panic Disorder, what is a reasonable alternative class?', '["TCA (e.g., Clomipramine, Imipramine)", "MAOI", "Benzodiazepines only", "Atypical antipsychotics"]', 0, 'TCAs are highly effective but second-line due to anticholinergic and cardiac toxicity. (MGH Pocket)'),
    (v_topic_id, '52: Are MAOIs effective for Panic Disorder?', '["No", "Yes, Phenelzine is highly effective but reserved for refractory cases due to dietary restrictions", "Only for MDD", "None"]', 1, 'Tyramine-free diet is required. (Kaplan & Sadock)'),
    (v_topic_id, '53: A patient on Phenelzine eats aged cheese and develops a severe headache, flushing, and BP of 220/120. Diagnosis?', '["Panic attack", "Hypertensive crisis", "Serotonin syndrome", "Stroke"]', 1, 'Due to tyramine displacing norepinephrine. (First Aid)'),
    (v_topic_id, '54: Treatment for MAOI-induced hypertensive crisis?', '["Propranolol", "Phentolamine (alpha blocker) or Nifedipine", "Alprazolam", "Epinephrine"]', 1, 'Must block alpha-1 receptors to lower BP. (MGH Pocket)'),
    (v_topic_id, '55: Are antipsychotics routinely used for Panic Disorder?', '["Yes", "No, lack of efficacy and high side effect burden", "First line", "None"]', 1, 'Only used as last resort adjuncts in severe, refractory anxiety. (Kaplan & Sadock)'),
    (v_topic_id, '56: What is "safety behavior" in Panic Disorder?', '["Calling the police", "Actions taken to prevent a feared outcome, which actually reinforce the anxiety (e.g., carrying an empty pill bottle just in case)", "Locking doors", "None"]', 1, 'CBT targets elimination of safety behaviors. (First Aid)'),
    (v_topic_id, '57: True or False: Mitral Valve Prolapse (MVP) is highly correlated with Panic Disorder.', '["True, historically thought to be linked, though the direct causation is debated", "False, completely unrelated", "True, MVP causes panic", "None"]', 0, 'Often comorbid, but treating MVP doesn''t cure the panic. (MGH Pocket)'),
    (v_topic_id, '58: Can caffeine trigger a panic attack in a susceptible individual?', '["No", "Yes, caffeine is anxiogenic and can induce panic", "Only in children", "None"]', 1, 'Caffeine acts as an adenosine antagonist. (Kaplan & Sadock)'),
    (v_topic_id, '59: What is the risk of comorbid MDD in Panic Disorder?', '["10%", "25%", "Up to 50-65%", "0%"]', 2, 'Highly comorbid. (First Aid)'),
    (v_topic_id, '60: Which statement best describes the natural course of untreated Panic Disorder?', '["Self-resolving in weeks", "Chronic but waxing and waning, often complicated by Agoraphobia and MDD", "Progresses to Schizophrenia", "Always fatal"]', 1, 'Early treatment prevents Agoraphobia. (MGH Pocket)'),

    -- SECTION 2: Generalized Anxiety Disorder (GAD) (71-140)
    (v_topic_id, '71: What is the defining feature of Generalized Anxiety Disorder (GAD)?', '["Unexpected panic attacks", "Excessive, difficult-to-control worry about everyday things (multiple domains) occurring more days than not", "Fear of social situations", "Obsessions"]', 1, 'Worry must cover multiple topics (health, finances, family). (DSM-5)'),
    (v_topic_id, '72: What is the minimum duration of symptoms required to diagnose GAD?', '["1 month", "3 months", "6 months", "1 year"]', 2, 'Must be present for at least 6 months. (First Aid)'),
    (v_topic_id, '73: How many of the 6 associated somatic/cognitive symptoms (e.g., restlessness, fatigue, poor concentration, irritability, muscle tension, sleep disturbance) are required for adults?', '["1", "3", "5", "All 6"]', 1, 'Requires at least 3 for adults (only 1 for children). (DSM-5)'),
    (v_topic_id, '74: Which physical symptom is highly characteristic of GAD and helps distinguish it from Panic Disorder?', '["Palpitations", "Muscle tension (e.g., neck/shoulder pain, headaches)", "Diaphoresis", "Tremor"]', 1, 'Muscle tension is a core feature of chronic worry. (Kaplan & Sadock)'),
    (v_topic_id, '75: A patient complains of chronic insomnia because they "can''t turn their brain off" worrying about their job, kids, and money. Diagnosis?', '["Insomnia disorder", "GAD", "MDD", "Panic Disorder"]', 1, 'Sleep disturbance (usually initial insomnia) is very common in GAD. (MGH Pocket)'),
    (v_topic_id, '76: First-line pharmacological treatment for GAD?', '["Benzodiazepines", "SSRIs (e.g., Escitalopram) or SNRIs (e.g., Venlafaxine, Duloxetine)", "Buspirone", "Haloperidol"]', 1, 'SSRIs/SNRIs treat the underlying worry pathway. (First Aid)'),
    (v_topic_id, '77: Which non-SSRI/SNRI medication is FDA approved specifically for GAD and has no risk of dependence?', '["Buspirone", "Alprazolam", "Quetiapine", "Pregabalin"]', 0, 'Buspirone is a 5-HT1A partial agonist; non-sedating, no addiction potential. (Kaplan & Sadock)'),
    (v_topic_id, '78: How long does Buspirone take to become effective?', '["1 hour", "1 day", "2-4 weeks", "6 months"]', 2, 'It cannot be used PRN (as needed) for anxiety; must be taken daily. (First Aid)'),
    (v_topic_id, '79: What is the role of Benzodiazepines in GAD?', '["First-line maintenance", "Second-line or short-term bridge therapy only, due to risk of tolerance and dependence", "Never use", "Only for children"]', 1, 'Avoid long-term use if possible. (MGH Pocket)'),
    (v_topic_id, '80: Which medication class (used off-label) is highly effective for the somatic symptoms of GAD and is widely used in Europe?', '["Beta blockers", "Gabapentinoids (Pregabalin, Gabapentin)", "Antipsychotics", "Lithium"]', 1, 'Pregabalin binds to voltage-gated calcium channels. (Kaplan & Sadock)'),
    (v_topic_id, '81: First-line psychotherapy for GAD?', '["Psychoanalysis", "CBT (Cognitive Behavioral Therapy)", "EMDR", "DBT"]', 1, 'Focuses on cognitive restructuring of worry and relaxation techniques. (First Aid)'),
    (v_topic_id, '82: What is "cognitive restructuring" in CBT for GAD?', '["Relaxing muscles", "Identifying and challenging catastrophic or irrational thoughts", "Ignoring thoughts", "None"]', 1, 'e.g., "If I lose my job, my life is over" -> "If I lose my job, I will find another one." (MGH Pocket)'),
    (v_topic_id, '83: Does GAD have a high or low rate of psychiatric comorbidity?', '["Low", "High (especially MDD, Social Anxiety, and Specific Phobias)", "None", "100%"]', 1, 'Rarely presents as a pure, isolated disorder. (Kaplan & Sadock)'),
    (v_topic_id, '84: What is the lifetime prevalence of GAD?', '["1%", "5-9%", "20%", "50%"]', 1, 'One of the most common anxiety disorders in primary care. (First Aid)'),
    (v_topic_id, '85: Are women or men more likely to be diagnosed with GAD?', '["Men", "Women (2:1 ratio)", "Equal", "None"]', 1, 'Consistent across most epidemiological studies. (MGH Pocket)'),
    (v_topic_id, '86: A 70yo patient presents with new-onset severe anxiety, weight loss, and tachycardia. Before diagnosing late-onset GAD, you MUST check:', '["MRI head", "TSH (to rule out Hyperthyroidism)", "Lithium level", "None"]', 1, 'Thyrotoxicosis perfectly mimics GAD/Panic. (Kaplan & Sadock)'),
    (v_topic_id, '87: Which GI condition is highly comorbid with GAD?', '["Ulcerative Colitis", "Irritable Bowel Syndrome (IBS)", "Celiac disease", "Crohn''s"]', 1, 'The "brain-gut" axis is highly active in chronic anxiety. (First Aid)'),
    (v_topic_id, '88: Which antihistamine is often used off-label as a non-addictive PRN anxiolytic in GAD?', '["Diphenhydramine", "Hydroxyzine", "Cetirizine", "Loratadine"]', 1, 'Provides mild sedation and anxiety relief without benzo risks. (MGH Pocket)'),
    (v_topic_id, '89: In children, how many somatic symptoms are required for a GAD diagnosis?', '["1", "3", "5", "6"]', 0, 'Only 1 is needed (e.g., restlessness). (DSM-5)'),
    (v_topic_id, '90: GAD vs Normal Worry: Normal worry is usually:', '["Controllable, proportion to the stressor, and does not cause severe impairment", "Uncontrollable", "Causes insomnia", "None"]', 0, 'GAD worry is pervasive and disabling. (Kaplan & Sadock)'),
    (v_topic_id, '91: Can GAD be diagnosed if the anxiety is confined ONLY to having a panic attack?', '["Yes", "No, that is Panic Disorder", "Yes, if it lasts 6 months", "None"]', 1, 'The worry in GAD must be generalized to multiple domains. (First Aid)'),
    (v_topic_id, '92: Can GAD be diagnosed if the anxiety is confined ONLY to gaining weight?', '["Yes", "No, that is Anorexia Nervosa", "Yes, if it lasts 6 months", "None"]', 1, 'Rule out specific focal fears like eating disorders. (MGH Pocket)'),
    (v_topic_id, '93: Can GAD be diagnosed if the anxiety is confined ONLY to being judged by others?', '["Yes", "No, that is Social Anxiety Disorder", "Yes, if it lasts 6 months", "None"]', 1, 'Rule out SAD. (Kaplan & Sadock)'),
    (v_topic_id, '94: Which brain region is believed to be underactive in GAD, failing to inhibit the amygdala?', '["Prefrontal cortex (specifically ventromedial PFC)", "Hippocampus", "Cerebellum", "Brainstem"]', 0, 'Top-down control is impaired. (First Aid)'),
    (v_topic_id, '95: A patient with GAD complains of "mind going blank." Is this a symptom criterion?', '["No", "Yes, poor concentration or mind going blank is one of the 6 core symptoms", "Only in kids", "None"]', 1, 'Very common cognitive complaint. (DSM-5)'),
    (v_topic_id, '96: Which antidepressant should generally be AVOIDED as first-line in GAD due to lack of efficacy for anxiety?', '["Sertraline", "Bupropion", "Escitalopram", "Venlafaxine"]', 1, 'Bupropion is activating (increases dopamine/norepinephrine) and can WORSEN anxiety. (MGH Pocket)'),
    (v_topic_id, '97: If a patient with GAD fails 2 SSRIs and 1 SNRI, what is a reasonable next step?', '["Buspirone augmentation, Pregabalin, or a TCA (Imipramine)", "Haloperidol", "ECT", "None"]', 0, 'Evidence-based next steps. (Kaplan & Sadock)'),
    (v_topic_id, '98: How long should you wait to assess the full efficacy of an SSRI in GAD?', '["1 week", "4-6 weeks (or up to 8-12 weeks)", "6 months", "1 year"]', 1, 'Patience is required. (First Aid)'),
    (v_topic_id, '99: A patient with GAD is started on Fluoxetine. One week later, they call saying their anxiety is MUCH worse. What happened?', '["Serotonin syndrome", "Activation syndrome (initial jitteriness/anxiety common with SSRIs)", "Mania", "Allergic reaction"]', 1, 'Why we "start low and go slow" in anxiety disorders. (MGH Pocket)'),
    (v_topic_id, '100: How do you manage SSRI activation syndrome?', '["Stop the drug immediately", "Reassure, lower the dose temporarily, or provide a short course of PRN benzos", "Add antipsychotic", "None"]', 1, 'Usually resolves in 1-2 weeks. (Kaplan & Sadock)'),
    (v_topic_id, '101: GAD and MDD share which symptoms?', '["Fatigue, poor concentration, sleep disturbance, psychomotor agitation/restlessness", "Delusions", "Anhedonia", "None"]', 0, 'High overlap in diagnostic criteria. (First Aid)'),
    (v_topic_id, '102: What distinguishes GAD from MDD?', '["GAD lacks anhedonia, profound sadness, and suicidality (though comorbid MDD is common)", "GAD has hallucinations", "MDD has no anxiety", "None"]', 0, 'Core affective state differs. (MGH Pocket)'),
    (v_topic_id, '103: Applied Relaxation Training (ART) is a behavioral technique used in GAD. What does it involve?', '["Medication", "Progressive muscle relaxation (tensing and relaxing muscle groups) to combat chronic muscle tension", "Hypnosis", "None"]', 1, 'Highly effective for the somatic symptoms. (Kaplan & Sadock)'),
    (v_topic_id, '104: Biofeedback in GAD typically monitors what?', '["EEG", "Heart rate, skin conductance (sweat), or muscle tension (EMG) to teach the patient to consciously lower autonomic arousal", "Urine output", "None"]', 1, 'A form of physiological CBT. (First Aid)'),
    (v_topic_id, '105: What is the role of Kava Kava in treating anxiety?', '["FDA approved first line", "Herbal supplement with anxiolytic properties, but carries a black box warning for severe hepatotoxicity", "Cures GAD", "None"]', 1, 'Physicians generally advise against it due to liver failure risk. (MGH Pocket)'),
    (v_topic_id, '106: What is the role of Valerian root in treating anxiety?', '["Herbal supplement that increases GABA; relatively safe but mild efficacy", "Toxic to kidneys", "FDA approved", "None"]', 0, 'Often used by patients for sleep/mild anxiety. (Kaplan & Sadock)'),
    (v_topic_id, '107: What is the risk of using Benzodiazepines in elderly patients with GAD?', '["No risk", "Increased risk of falls, hip fractures, paradoxical agitation, and cognitive impairment (dementia-like state)", "Liver failure", "None"]', 1, 'Strictly avoid long-acting benzos (diazepam, clonazepam) in the elderly. (First Aid)'),
    (v_topic_id, '108: If a benzo MUST be used in an elderly patient or one with liver failure, which are preferred?', '["Diazepam", "The LOT benzos (Lorazepam, Oxazepam, Temazepam) because they do not require hepatic oxidation, only glucuronidation", "Alprazolam", "Clonazepam"]', 1, 'Board classic: "LOT" benzos are safer in liver dysfunction. (MGH Pocket)'),
    (v_topic_id, '109: What is paradoxical agitation with Benzodiazepines?', '["Sedation", "Instead of calming, the drug causes disinhibition, excitement, and aggression (more common in elderly/children)", "Seizures", "None"]', 1, 'Similar to alcohol disinhibition. (Kaplan & Sadock)'),
    (v_topic_id, '110: A patient taking daily Alprazolam for 5 years runs out of their prescription. 48 hours later, they develop tachycardia, tremors, and have a grand mal seizure. Diagnosis?', '["Epilepsy", "Benzodiazepine withdrawal", "Panic attack", "Meningitis"]', 1, 'Life-threatening emergency. (First Aid)'),
    (v_topic_id, '111: Treatment for Benzodiazepine withdrawal?', '["Flumazenil", "Reinstitute a long-acting benzodiazepine (e.g., Diazepam or Chlordiazepoxide) and taper slowly", "Haloperidol", "Phenytoin"]', 1, 'Never give Flumazenil (it will cause intractable seizures). (MGH Pocket)'),
    (v_topic_id, '112: Flumazenil is a GABA-A receptor antagonist used for Benzodiazepine overdose. Why is it rarely used in clinical practice?', '["It doesn''t work", "It can precipitate acute withdrawal and fatal seizures in dependent patients", "It causes liver failure", "None"]', 1, 'Supportive care (intubation if necessary) is preferred for benzo OD. (Kaplan & Sadock)'),
    (v_topic_id, '113: Which medication is FDA approved for GAD and also treats diabetic peripheral neuropathy and fibromyalgia?', '["Duloxetine (SNRI)", "Fluoxetine", "Buspirone", "Alprazolam"]', 0, 'Hits serotonin and norepinephrine, good for pain + anxiety. (First Aid)'),
    (v_topic_id, '114: Which medication is FDA approved for GAD and also treats hot flashes in menopause?', '["Escitalopram", "Venlafaxine (SNRI)", "Buspirone", "Pregabalin"]', 1, 'SNRI utility. (MGH Pocket)'),
    (v_topic_id, '115: What is the primary psychological defense mechanism seen in GAD?', '["Denial", "Intellectualization or Displacement", "Projection", "Splitting"]', 1, 'Displacing unconscious anxiety onto safe, everyday worries. (Kaplan & Sadock)'),
    (v_topic_id, '116: According to cognitive theory, worry in GAD serves what function?', '["To cause pain", "It is an attempt at problem-solving and an avoidance strategy to prevent feeling deeper, more intense negative emotions", "None", "None"]', 1, 'Worry paradoxically reduces acute autonomic arousal. (First Aid)'),
    (v_topic_id, '117: Intolerance of Uncertainty is a core psychological feature of which disorder?', '["Schizophrenia", "GAD", "Bipolar", "None"]', 1, 'Patients cannot tolerate the idea that a negative event *might* happen. (MGH Pocket)'),
    (v_topic_id, '118: A 10-year-old child worries constantly about their grades, a potential war, and their parents'' health. They need constant reassurance and have frequent stomach aches. Diagnosis?', '["Separation Anxiety", "GAD", "Social Anxiety", "Normal"]', 1, 'GAD in children often presents with somatic complaints and perfectionism. (Kaplan & Sadock)'),
    (v_topic_id, '119: Separation Anxiety Disorder in children is characterized by:', '["Worry about everything", "Developmentally inappropriate fear of separation from attachment figures (e.g., fear parents will die if they leave)", "Fear of school", "None"]', 1, 'Must last at least 4 weeks in children (6 months in adults). (DSM-5)'),
    (v_topic_id, '120: Treatment for Separation Anxiety in children?', '["Benzodiazepines", "CBT, family therapy, and graded return to school (SSRIs if severe)", "Homeschooling", "None"]', 1, 'Do not keep the child out of school (reinforces avoidance). (First Aid)'),
    (v_topic_id, '121: GAD vs Panic Disorder: Autonomic arousal?', '["Panic = High autonomic arousal (tachycardia); GAD = Lower autonomic arousal, higher muscle tension", "Both high", "Both low", "None"]', 0, 'Physiological distinction. (MGH Pocket)'),
    (v_topic_id, '122: GAD vs OCD?', '["GAD = worry about real-life issues; OCD = intrusive, ego-dystonic obsessions often leading to compulsions", "They are the same", "None", "None"]', 0, 'Worry vs Obsession. (Kaplan & Sadock)'),
    (v_topic_id, '123: GAD vs Illness Anxiety Disorder (Hypochondriasis)?', '["GAD = worries about many things including health; IAD = worry is SOLELY about having a serious illness despite medical reassurance", "None", "None", "None"]', 0, 'Scope of worry. (First Aid)'),
    (v_topic_id, '124: What is the role of Mindfulness-Based Stress Reduction (MBSR) in GAD?', '["Not effective", "Highly effective adjunct; teaches present-moment awareness to break the cycle of future-oriented worry", "First line meds", "None"]', 1, 'Becoming a standard therapy. (MGH Pocket)'),
    (v_topic_id, '125: Which demographic has the highest rate of GAD?', '["Children", "Young adults", "Middle-aged adults (peaks here)", "Elderly"]', 2, 'Though it can present at any age. (Kaplan & Sadock)'),
    (v_topic_id, '126: GAD patients often present to which medical setting first?', '["Psychiatry", "Primary care, Cardiology, or Gastroenterology", "Surgery", "None"]', 1, 'Due to prominent somatic symptoms (headache, IBS, chest tightness). (First Aid)'),
    (v_topic_id, '127: The "worry" in GAD is considered:', '["Ego-dystonic", "Ego-syntonic (the patient feels the worry is justified, even if excessive)", "Psychotic", "None"]', 1, 'Unlike OCD obsessions which are ego-dystonic. (MGH Pocket)'),
    (v_topic_id, '128: How does caffeine affect GAD?', '["Improves it", "Exacerbates anxiety, insomnia, and somatic symptoms; patients should be advised to reduce intake", "No effect", "None"]', 1, 'Basic lifestyle modification. (Kaplan & Sadock)'),
    (v_topic_id, '129: What is "autonomic rigidity" in GAD?', '["Decreased heart rate variability (HRV); the autonomic nervous system loses its flexible response to stress", "High HRV", "None", "None"]', 0, 'A physiological marker of chronic anxiety. (First Aid)'),
    (v_topic_id, '130: Does GAD increase cardiovascular mortality?', '["No", "Yes, chronic sympathetic overdrive increases the risk of coronary artery disease and fatal arrhythmias", "Only in men", "None"]', 1, 'Anxiety is cardiotoxic over decades. (MGH Pocket)'),
    (v_topic_id, '131: A pregnant patient with GAD requires medication. Which SSRI is notoriously teratogenic (Category D, causes cardiac septal defects)?', '["Sertraline", "Paroxetine", "Fluoxetine", "Citalopram"]', 1, 'Avoid Paroxetine in pregnancy. (Kaplan & Sadock)'),
    (v_topic_id, '132: Which SSRI is considered one of the safest in pregnancy?', '["Paroxetine", "Sertraline", "Valproate", "None"]', 1, 'Sertraline and Escitalopram are generally preferred. (First Aid)'),
    (v_topic_id, '133: Are Benzodiazepines safe in pregnancy?', '["Yes", "No, associated with cleft lip/palate (1st trimester) and ''floppy infant syndrome'' (3rd trimester)", "Only Diazepam", "None"]', 1, 'Avoid if possible. (MGH Pocket)'),
    (v_topic_id, '134: Buspirone mechanism of action?', '["GABA agonist", "5-HT1A partial agonist", "Dopamine antagonist", "SSRI"]', 1, 'Unique mechanism. (Kaplan & Sadock)'),
    (v_topic_id, '135: Does Buspirone interact with alcohol?', '["Yes, fatally", "No, it does NOT potentiate the CNS depressant effects of alcohol (unlike benzos)", "Causes vomiting", "None"]', 1, 'A major advantage over benzos. (First Aid)'),
    (v_topic_id, '136: GAD diagnostic mnemonic "Macbeth Frets Constantly Regarding Illicit Sins" stands for?', '["None", "Muscle tension, Fatigue, Concentration issues, Restlessness, Irritability, Sleep issues", "None", "None"]', 1, 'The 6 somatic symptoms. (MGH Pocket)'),
    (v_topic_id, '137: A patient with GAD starts taking St. John''s Wort over the counter while on Sertraline. What is the risk?', '["Nothing", "Serotonin Syndrome (St. John''s Wort is a mild MAOI/serotonergic agent)", "Liver failure", "None"]', 1, 'Must ask about herbal supplements. (Kaplan & Sadock)'),
    (v_topic_id, '138: Serotonin Syndrome triad?', '["Altered mental status, Autonomic instability (fever, tachycardia), Neuromuscular hyperactivity (clonus, hyperreflexia)", "Rigidity", "None", "None"]', 0, 'Life threatening. (First Aid)'),
    (v_topic_id, '139: Treatment for Serotonin Syndrome?', '["Dantrolene", "Stop serotonergic agents, supportive care, Cyproheptadine (5-HT2 antagonist) if severe", "Haloperidol", "None"]', 1, 'Cyproheptadine is the antidote. (MGH Pocket)'),
    (v_topic_id, '140: Can untreated GAD lead to secondary substance abuse?', '["No", "Yes, up to 30% of patients self-medicate with alcohol or sedatives", "Only in men", "None"]', 1, 'Dual diagnosis is common. (Kaplan & Sadock)'),

    -- SECTION 3: Specific Phobias & Social Anxiety Disorder (141-210)
    (v_topic_id, '141: What is the defining feature of a Specific Phobia?', '["Fear of panic attacks", "Marked, disproportionate fear of a specific object or situation that is actively avoided", "Fear of social judgment", "None"]', 1, 'e.g., spiders, heights, flying. (DSM-5)'),
    (v_topic_id, '142: How long must symptoms be present to diagnose Specific Phobia?', '["1 month", "6 months", "1 year", "2 weeks"]', 1, 'Consistent with most anxiety disorders. (First Aid)'),
    (v_topic_id, '143: Does the patient recognize the fear is excessive/irrational in Specific Phobia?', '["No, they are delusional", "Yes, adults usually retain insight that the fear is out of proportion to the actual danger", "Only women do", "None"]', 1, 'Insight is typically intact. (MGH Pocket)'),
    (v_topic_id, '144: What is the most effective treatment for Specific Phobia?', '["SSRIs", "Benzodiazepines", "Cognitive Behavioral Therapy with EXPOSURE therapy (Systematic Desensitization or Flooding)", "Psychoanalysis"]', 2, 'Medications generally have little role unless used acutely for a rare, unavoidable exposure (e.g., benzo before a flight). (Kaplan & Sadock)'),
    (v_topic_id, '145: What is "Systematic Desensitization"?', '["Throwing them in a room of spiders", "Teaching relaxation techniques while gradually exposing the patient to a hierarchy of feared stimuli (from least to most scary)", "Ignoring it", "None"]', 1, 'Gold standard behavioral therapy. (First Aid)'),
    (v_topic_id, '146: What is "Flooding"?', '["Gradual exposure", "Immediate, full exposure to the most feared stimulus until the anxiety eventually exhausts itself (habituation)", "Water therapy", "None"]', 1, 'Effective but highly distressing; high dropout rate. (MGH Pocket)'),
    (v_topic_id, '147: Which specific phobia subtype is UNIQUE because it causes a vasovagal response (bradycardia and hypotension) leading to fainting, rather than tachycardia?', '["Animal type", "Natural environment type", "Blood-Injection-Injury (BII) type", "Situational type"]', 2, 'Classic board question. (Kaplan & Sadock)'),
    (v_topic_id, '148: How is the behavioral therapy for Blood-Injection-Injury phobia different from other phobias?', '["You use flooding", "Instead of relaxation, you teach Applied Tension (tensing muscles to raise blood pressure and prevent fainting) during exposure", "You use meds", "None"]', 1, 'Relaxation would actually make them faint faster! (First Aid)'),
    (v_topic_id, '149: Acrophobia is the fear of:', '["Spiders", "Heights", "Closed spaces", "Open spaces"]', 1, 'A natural environment phobia. (MGH Pocket)'),
    (v_topic_id, '150: Claustrophobia is the fear of:', '["Heights", "Enclosed spaces (e.g., MRI machines, elevators)", "Spiders", "Flying"]', 1, 'A situational phobia. (Kaplan & Sadock)'),
    (v_topic_id, '151: Arachnophobia is the fear of:', '["Snakes", "Spiders", "Dogs", "Birds"]', 1, 'Animal subtype. (First Aid)'),
    (v_topic_id, '152: Ophidiophobia is the fear of:', '["Spiders", "Snakes", "Heights", "Blood"]', 1, 'Animal subtype. (MGH Pocket)'),
    (v_topic_id, '153: Glossophobia is the fear of:', '["Glass", "Public speaking", "Tongues", "Open spaces"]', 1, 'Often falls under Social Anxiety Disorder (Performance only). (Kaplan & Sadock)'),
    (v_topic_id, '154: Trypanophobia is the fear of:', '["Triangles", "Needles/Injections", "Flying", "Spiders"]', 1, 'Blood-Injection-Injury subtype. (First Aid)'),
    (v_topic_id, '155: Aviophobia is the fear of:', '["Birds", "Flying", "Water", "Dirt"]', 1, 'Situational subtype. (MGH Pocket)'),
    (v_topic_id, '156: Cynophobia is the fear of:', '["Cats", "Dogs", "Cynics", "Color"]', 1, 'Animal subtype. (Kaplan & Sadock)'),
    (v_topic_id, '157: What is the most common mental disorder in the United States overall?', '["Major Depressive Disorder", "Specific Phobia", "Schizophrenia", "Panic Disorder"]', 1, 'Prevalence is ~10-12%, though many don''t seek treatment. (First Aid)'),
    (v_topic_id, '158: What is the defining feature of Social Anxiety Disorder (SAD)?', '["Fear of spiders", "Marked fear of social or performance situations where the individual is exposed to possible SCRUTINY or NEGATIVE EVALUATION by others", "Fear of panic attacks", "None"]', 1, 'Fear of embarrassment or humiliation. (DSM-5)'),
    (v_topic_id, '159: To diagnose Social Anxiety Disorder, the symptoms must last:', '["1 month", "6 months", "1 year", "2 weeks"]', 1, 'Consistent with other anxiety disorders. (First Aid)'),
    (v_topic_id, '160: First-line pharmacological treatment for generalized Social Anxiety Disorder?', '["Beta blockers", "SSRIs (e.g., Paroxetine, Sertraline) or SNRIs", "Benzodiazepines", "Haloperidol"]', 1, 'SSRIs are the gold standard for daily maintenance. (MGH Pocket)'),
    (v_topic_id, '161: First-line psychotherapy for Social Anxiety Disorder?', '["CBT with social exposure and cognitive restructuring", "Psychoanalysis", "EMDR", "None"]', 0, 'Challenging the belief that others are judging them. (Kaplan & Sadock)'),
    (v_topic_id, '162: What is the "Performance Only" specifier for Social Anxiety Disorder?', '["The fear is only of sexual performance", "The fear is restricted to speaking or performing in public (no fear of casual social interaction)", "None", "None"]', 1, 'e.g., stage fright. (DSM-5)'),
    (v_topic_id, '163: Best treatment for "Performance Only" Social Anxiety Disorder (e.g., taking an oral exam)?', '["Daily SSRI", "PRN Beta-blockers (e.g., Propranolol) taken 30-60 mins before the event to block autonomic arousal (tremor, tachycardia)", "Daily Benzo", "ECT"]', 1, 'Highly effective for stage fright. (First Aid)'),
    (v_topic_id, '164: Who should NOT receive Propranolol for performance anxiety?', '["Patients with asthma, severe bradycardia, or heart block", "Patients with hypertension", "Patients with depression", "None"]', 0, 'Non-selective beta blockers can trigger bronchospasm. (MGH Pocket)'),
    (v_topic_id, '165: A patient fears eating in public, using public restrooms, and speaking in class. Diagnosis?', '["Agoraphobia", "Generalized Social Anxiety Disorder", "Panic Disorder", "Specific Phobia"]', 1, 'The core fear is SCRUTINY/embarrassment, not panic/escape (Agoraphobia). (Kaplan & Sadock)'),
    (v_topic_id, '166: Selective Mutism in children is strongly related to which adult disorder?', '["Schizophrenia", "Social Anxiety Disorder", "Autism", "ADHD"]', 1, 'Failure to speak in specific social situations (e.g., school) despite speaking normally at home. (First Aid)'),
    (v_topic_id, '167: Diagnostic criteria for Selective Mutism requires duration of at least:', '["1 week", "1 month (excluding the first month of school)", "6 months", "1 year"]', 1, 'First month of school doesn''t count due to normal adjustment. (DSM-5)'),
    (v_topic_id, '168: Treatment for Selective Mutism?', '["Forcing the child to speak", "CBT, play therapy, family therapy, and SSRIs if severe/refractory", "Antipsychotics", "None"]', 1, 'Never pressure the child to speak; use reward systems. (MGH Pocket)'),
    (v_topic_id, '169: Avoidant Personality Disorder is highly comorbid with and deeply related to:', '["Schizophrenia", "Social Anxiety Disorder (many consider APD a more severe, pervasive variant of SAD)", "Narcissistic PD", "None"]', 1, 'Pervasive pattern of social inhibition, feelings of inadequacy, and hypersensitivity to rejection. (Kaplan & Sadock)'),
    (v_topic_id, '170: Taijin Kyofusho (culture-bound syndrome in Japan/Korea) differs from typical Social Anxiety Disorder because:', '["The fear is of panic attacks", "The primary fear is that one''s body or actions will OFFEND or embarrass OTHERS, rather than embarrassing oneself", "None", "None"]', 1, 'An allocentric (other-focused) vs egocentric fear. (First Aid)'),
    (v_topic_id, '171: Typical age of onset for Social Anxiety Disorder?', '["Late adulthood", "Childhood or early adolescence (median age 13)", "Infancy", "Middle age"]', 1, 'Rarely starts after age 25. (MGH Pocket)'),
    (v_topic_id, '172: What is the risk of alcohol use in Social Anxiety Disorder?', '["Low", "Extremely high; patients self-medicate to reduce inhibition (''liquid courage'')", "None", "None"]', 1, 'Dual diagnosis is rampant. (Kaplan & Sadock)'),
    (v_topic_id, '173: A patient drinks 4 beers before every social event to calm their nerves. Best approach?', '["Tell them to drink more", "Treat the underlying Social Anxiety with SSRI/CBT, which will likely reduce the secondary alcohol abuse", "Give benzos", "None"]', 1, 'Treat the primary disorder. (First Aid)'),
    (v_topic_id, '174: Social Anxiety Disorder vs Schizoid Personality Disorder?', '["Schizoid patients WANT friends but are afraid; SAD patients don''t want friends", "SAD patients desire relationships but fear rejection; Schizoid patients lack the desire for social intimacy", "They are the same", "None"]', 1, 'SAD = lonely. Schizoid = content alone. (MGH Pocket)'),
    (v_topic_id, '175: Social Anxiety vs Autism Spectrum Disorder?', '["Autism lacks social skills/theory of mind; SAD has intact social skills but severe anxiety inhibits them", "SAD lacks social skills", "None", "None"]', 0, 'Fundamental difference in capacity vs performance. (Kaplan & Sadock)'),
    (v_topic_id, '176: Can a Specific Phobia trigger a Panic Attack?', '["No", "Yes, a ''cued'' or ''expected'' panic attack", "Only in men", "None"]', 1, 'This does NOT mean they have Panic Disorder. (First Aid)'),
    (v_topic_id, '177: What happens to heart rate when a patient with a needle phobia gets an injection?', '["Initial tachycardia followed by sudden severe bradycardia (vasovagal syncope)", "Constant tachycardia", "No change", "None"]', 0, 'The biphasic response. (MGH Pocket)'),
    (v_topic_id, '178: Paruresis ("shy bladder syndrome") is considered a form of:', '["Specific phobia", "Social Anxiety Disorder", "Panic disorder", "OCD"]', 1, 'Fear of scrutiny while urinating in public restrooms. (Kaplan & Sadock)'),
    (v_topic_id, '179: Erythrophobia is the fear of:', '["Red colors", "Blushing (highly associated with Social Anxiety Disorder)", "Blood", "Earth"]', 1, 'Blushing is a prominent autonomic symptom in SAD. (First Aid)'),
    (v_topic_id, '180: What is "in vivo" exposure?', '["Imagining the fear", "Virtual reality", "Actual, real-life exposure to the feared stimulus", "None"]', 2, 'The most effective form of exposure therapy. (MGH Pocket)'),
    (v_topic_id, '181: What is "imaginal" exposure?', '["Real life", "Having the patient vividly imagine the feared scenario", "Watching a movie", "None"]', 1, 'Used when in vivo is impractical (e.g., fear of plane crashes). (Kaplan & Sadock)'),
    (v_topic_id, '182: Can virtual reality (VR) be used for exposure therapy?', '["No", "Yes, VR exposure therapy (VRET) is highly effective for fear of flying, heights, and PTSD", "Only for kids", "None"]', 1, 'A growing, evidence-based modality. (First Aid)'),
    (v_topic_id, '183: What is "Modeling" in behavioral therapy?', '["Building models", "The therapist interacts with the feared object first to demonstrate it is safe (e.g., therapist holds the spider first)", "None", "None"]', 1, 'Vicarious learning. (MGH Pocket)'),
    (v_topic_id, '184: Which medication is sometimes given 1-2 hours BEFORE an exposure therapy session to ENHANCE learning and extinction of fear?', '["Alprazolam", "D-cycloserine (an NMDA receptor partial agonist)", "Haloperidol", "Fluoxetine"]', 1, 'Enhances neuroplasticity in the amygdala during exposure. (Kaplan & Sadock)'),
    (v_topic_id, '185: Why should Benzodiazepines generally be AVOIDED during exposure therapy?', '["They cause seizures", "They reduce the anxiety too much, preventing the patient from fully experiencing and habituating to the fear, thus impairing learning", "None", "None"]', 1, 'State-dependent learning; if they learn it while sedated, it doesn''t transfer to a sober state. (First Aid)'),
    (v_topic_id, '186: Does Social Anxiety Disorder respond to MAOIs?', '["No", "Yes, Phenelzine is highly effective, but reserved for refractory cases due to diet restrictions", "Only in women", "None"]', 1, 'Historically very successful for SAD. (MGH Pocket)'),
    (v_topic_id, '187: A child throws tantrums, cries, and clings to their parents ONLY when approaching dogs. Diagnosis?', '["Separation anxiety", "Specific Phobia (children express fear via crying/tantrums)", "Autism", "Normal"]', 1, 'Age-appropriate expression of a phobia. (Kaplan & Sadock)'),
    (v_topic_id, '188: A child refuses to go to school because they are bullied. Is this Social Anxiety Disorder?', '["Yes", "No, this is a realistic fear of an actual threat, not an irrational fear of scrutiny", "It is Agoraphobia", "None"]', 1, 'Must differentiate pathological anxiety from realistic danger. (First Aid)'),
    (v_topic_id, '189: A patient with Parkinson''s disease avoids eating in public because they fear their severe tremor will disgust people. Diagnosis?', '["Social Anxiety Disorder", "Normal reaction", "Anxiety disorder due to another medical condition (if the anxiety is EXTREMELY out of proportion)", "None"]', 2, 'DSM-5 allows the diagnosis if the anxiety is clearly excessive relative to the medical issue. (DSM-5)'),
    (v_topic_id, '190: What is the "Spotlight Effect"?', '["A lighting technique", "The cognitive bias in Social Anxiety where patients believe everyone is noticing and judging their every move", "None", "None"]', 1, 'CBT aims to reduce this bias. (MGH Pocket)'),
    (v_topic_id, '191: Which neurotransmitter system is heavily targeted by Propranolol?', '["Serotonin", "GABA", "Beta-adrenergic (Norepinephrine)", "Dopamine"]', 2, 'Blocks peripheral sympathetic arousal. (Kaplan & Sadock)'),
    (v_topic_id, '192: Agoraphobia vs Social Anxiety Disorder (SAD): A patient refuses to go to a crowded mall.', '["Agoraphobia fears being trapped/panic; SAD fears people judging them at the mall", "They are the same", "None", "None"]', 0, 'The underlying MOTIVATION for avoidance is key. (First Aid)'),
    (v_topic_id, '193: Specific Phobia vs Schizophrenia: A patient avoids spiders because they believe spiders are alien spies.', '["Specific phobia", "Schizophrenia (this is a bizarre delusion, not a simple phobia)", "SAD", "None"]', 1, 'Psychotic avoidance vs neurotic avoidance. (MGH Pocket)'),
    (v_topic_id, '194: What evolutionary theory explains why fear of snakes/spiders is more common than fear of guns/cars?', '["Preparedness theory (we are evolutionarily hardwired to easily learn fears of ancient threats)", "Freudian theory", "None", "None"]', 0, 'Biological preparedness. (Kaplan & Sadock)'),
    (v_topic_id, '195: According to Freud, what caused "Little Hans" to have a phobia of horses?', '["A real horse bit him", "Displacement of unconscious Oedipal castration anxiety (fear of his father) onto the horse", "Genetics", "None"]', 1, 'Classic psychoanalytic theory of phobias. (First Aid)'),
    (v_topic_id, '196: According to Watson (Behaviorism), how did "Little Albert" develop a phobia of white rats?', '["Classical conditioning (pairing a loud scary noise with the rat)", "Genetics", "Oedipus complex", "None"]', 0, 'Behavioral theory of phobia acquisition. (MGH Pocket)'),
    (v_topic_id, '197: According to Skinner, how are phobias MAINTAINED?', '["Classical conditioning", "Operant conditioning (avoiding the object reduces anxiety, which is NEGATIVE REINFORCEMENT, making avoidance more likely next time)", "Punishment", "None"]', 1, 'Mowrer''s Two-Factor Theory. (Kaplan & Sadock)'),
    (v_topic_id, '198: Therefore, the goal of exposure therapy is to prevent which behavior?', '["Crying", "Avoidance (so that extinction can occur)", "Talking", "None"]', 1, 'Stopping the negative reinforcement cycle. (First Aid)'),
    (v_topic_id, '199: A patient with Social Anxiety is prescribed Phenelzine (MAOI). They must avoid foods rich in:', '["Vitamin K", "Tyramine (aged cheese, cured meats, draft beer)", "Gluten", "Dairy"]', 1, 'To prevent hypertensive crisis. (MGH Pocket)'),
    (v_topic_id, '200: A patient with Social Anxiety is prescribed Paroxetine. They complain of delayed ejaculation. Is this common?', '["No", "Yes, SSRIs commonly cause sexual dysfunction", "Only in elderly", "None"]', 1, 'A major reason for non-compliance. (Kaplan & Sadock)'),
    (v_topic_id, '201: If a patient with SAD cannot tolerate SSRI-induced sexual dysfunction, what is an alternative?', '["Venlafaxine", "Mirtazapine or SNRI (though SNRI still has risk)", "Clomipramine", "Stop meds"]', 1, 'Or add Bupropion (though Bupropion is not great for primary anxiety). (First Aid)'),
    (v_topic_id, '202: Can Gabapentin be used for Social Anxiety Disorder?', '["No", "Yes, used off-label for patients who fail or cannot tolerate SSRIs", "FDA approved first line", "None"]', 1, 'Has anxiolytic properties. (MGH Pocket)'),
    (v_topic_id, '203: A 15yo girl avoids eating in the cafeteria, fears reading aloud, and has few friends. Diagnosis?', '["Avoidant PD", "Social Anxiety Disorder", "Normal teen", "Schizoid PD"]', 1, 'Classic presentation. (Kaplan & Sadock)'),
    (v_topic_id, '204: A 40yo man has a lifelong fear of flying. He gets a new job requiring air travel. Best treatment?', '["Quit the job", "CBT with virtual reality or in vivo exposure (can give short-acting benzo PRN for the first flight if urgent)", "Daily SSRI", "None"]', 1, 'Targeted treatment for situational phobia. (First Aid)'),
    (v_topic_id, '205: A patient fears clowns. What is the clinical term?', '["Coulrophobia", "Arachnophobia", "Acrophobia", "Claustrophobia"]', 0, 'A type of specific phobia. (MGH Pocket)'),
    (v_topic_id, '206: A patient fears the number 13. Term?', '["Triskaidekaphobia", "Coulrophobia", "None", "None"]', 0, 'Can be phobia or part of OCD. (Kaplan & Sadock)'),
    (v_topic_id, '207: A patient fears vomiting in public. This can be classified as:', '["Emetophobia (Specific Phobia) or Social Anxiety Disorder, depending on the core motivation", "Panic disorder", "None", "None"]', 0, 'Requires careful history to determine the core fear. (First Aid)'),
    (v_topic_id, '208: Is pharmacotherapy effective for specific phobias?', '["Highly effective", "Generally ineffective; behavioral therapy is the treatment of choice", "First line", "None"]', 1, 'Meds don''t cure specific phobias. (MGH Pocket)'),
    (v_topic_id, '209: The anxiety in SAD is mediated primarily by hyper-reactivity of the:', '["Cerebellum", "Amygdala and insula", "Motor cortex", "None"]', 1, 'The emotion centers. (Kaplan & Sadock)'),
    (v_topic_id, '210: Summary: Best long term med for SAD?', '["SSRI", "Propranolol", "Benzo", "None"]', 0, 'SSRIs are the backbone of anxiety psychopharmacology. (First Aid)'),

    -- SECTION 4: Obsessive-Compulsive Disorder & Related (211-280)
    (v_topic_id, '211: What is an "Obsession"?', '["A repetitive action", "Recurrent, intrusive, and unwanted thoughts, urges, or images that cause marked anxiety or distress", "A delusion", "None"]', 1, 'They are ego-dystonic. (DSM-5)'),
    (v_topic_id, '212: What is a "Compulsion"?', '["An intrusive thought", "Repetitive behaviors or mental acts the individual feels driven to perform in response to an obsession, aimed at reducing anxiety", "A tic", "None"]', 1, 'The action taken to neutralize the obsession. (DSM-5)'),
    (v_topic_id, '213: Does a patient need BOTH obsessions and compulsions for an OCD diagnosis?', '["Yes", "No, either obsessions OR compulsions (or both) are required", "Must have compulsions only", "None"]', 1, 'Most have both, but one is sufficient. (First Aid)'),
    (v_topic_id, '214: Are the obsessions in OCD ego-syntonic or ego-dystonic?', '["Ego-syntonic", "Ego-dystonic (the patient recognizes them as irrational and unwanted)", "Psychotic", "None"]', 1, 'Unlike OCPD, where traits are ego-syntonic. (Kaplan & Sadock)'),
    (v_topic_id, '215: What is the most common obsession theme?', '["Symmetry", "Contamination", "Harm/Aggression", "Sexual"]', 1, 'Leads to washing/cleaning compulsions. (MGH Pocket)'),
    (v_topic_id, '216: A patient obsessively worries they left the stove on and their house will burn down. The compulsion is:', '["Washing hands", "Checking the stove 20 times before leaving", "Counting to 10", "None"]', 1, 'Pathological doubt -> Checking compulsion. (First Aid)'),
    (v_topic_id, '217: A patient has intrusive, horrifying images of stabbing their own child, which they find repulsive. Diagnosis?', '["Schizophrenia", "OCD (Harm obsession)", "Postpartum psychosis", "None"]', 1, 'Patients with OCD almost NEVER act on these aggressive obsessions. (Kaplan & Sadock)'),
    (v_topic_id, '218: A patient must tap the door frame exactly 4 times before entering, otherwise they feel their mother will die. This is an example of:', '["Magical thinking", "Delusion", "Psychosis", "None"]', 0, 'Common in OCD. (MGH Pocket)'),
    (v_topic_id, '219: What is the time criterion for OCD?', '["The obsessions/compulsions must be time-consuming (e.g., > 1 hour per day) OR cause clinically significant distress/impairment", "24 hours a day", "1 week", "None"]', 0, 'Differentiates OCD from normal quirks. (DSM-5)'),
    (v_topic_id, '220: First-line pharmacological treatment for OCD?', '["Haloperidol", "SSRIs (e.g., Fluvoxamine, Sertraline, Fluoxetine) at HIGH DOSES", "Benzodiazepines", "Lithium"]', 1, 'OCD typically requires much higher SSRI doses than depression. (First Aid)'),
    (v_topic_id, '221: Which TCA is highly serotonergic and FDA approved for OCD (often used second-line)?', '["Amitriptyline", "Clomipramine", "Nortriptyline", "Imipramine"]', 1, 'Considered the most efficacious drug for OCD, but side effects limit first-line use. (Kaplan & Sadock)'),
    (v_topic_id, '222: First-line psychotherapy for OCD?', '["Psychoanalysis", "Cognitive Behavioral Therapy with Exposure and Response Prevention (ERP)", "EMDR", "Supportive therapy"]', 1, 'ERP is the gold standard. (MGH Pocket)'),
    (v_topic_id, '223: What does "Response Prevention" mean in ERP?', '["Preventing the patient from talking", "Exposing the patient to the obsession (e.g., dirt) and PREVENTING them from performing the compulsion (e.g., washing hands)", "None", "None"]', 1, 'Forces habituation to the anxiety. (First Aid)'),
    (v_topic_id, '224: A patient has OCD that is refractory to SSRIs and Clomipramine. What is a common pharmacological augmentation strategy?', '["Add Lithium", "Add a Second-Generation Antipsychotic (e.g., Risperidone, Aripiprazole) in low doses", "Add Benzos", "Add MAOI"]', 1, 'Especially useful if there are comorbid tics. (Kaplan & Sadock)'),
    (v_topic_id, '225: What is the most extreme neurosurgical treatment for severe, completely refractory, debilitating OCD?', '["Lobotomy", "Deep Brain Stimulation (DBS) or Ablative surgery (e.g., Anterior Cingulotomy)", "ECT", "None"]', 1, 'Targets the cortico-striato-thalamo-cortical (CSTC) circuit. (MGH Pocket)'),
    (v_topic_id, '226: Which neuroanatomical circuit is hyperactive in OCD?', '["Nigrostriatal pathway", "Cortico-Striato-Thalamo-Cortical (CSTC) circuit (specifically orbitofrontal cortex and caudate nucleus)", "Mesolimbic", "None"]', 1, 'The brain''s "worry loop" gets stuck. (First Aid)'),
    (v_topic_id, '227: What is PANDAS?', '["A bear", "Pediatric Autoimmune Neuropsychiatric Disorders Associated with Streptococcal infections", "A genetic disease", "None"]', 1, 'Sudden, overnight onset of severe OCD and/or tics in a child following a Group A Strep infection. (Kaplan & Sadock)'),
    (v_topic_id, '228: Mechanism of PANDAS?', '["Viral encephalitis", "Cross-reactive antibodies (molecular mimicry) attacking the basal ganglia", "Toxins", "None"]', 1, 'Similar pathophysiology to Sydenham chorea. (MGH Pocket)'),
    (v_topic_id, '229: OCD is highly comorbid with which movement disorder?', '["Parkinson''s", "Tourette''s Disorder", "Huntington''s", "Essential Tremor"]', 1, 'High genetic crossover; up to 30% of OCD patients have a history of tics. (First Aid)'),
    (v_topic_id, '230: Obsessive-Compulsive Personality Disorder (OCPD) differs from OCD because OCPD:', '["Has true obsessions/compulsions", "Involves a pervasive pattern of perfectionism, orderliness, and control, but NO true obsessions or compulsions. It is EGO-SYNTONIC.", "Is treated with antipsychotics", "None"]', 1, 'Crucial distinction for boards. (Kaplan & Sadock)'),
    (v_topic_id, '231: Does a patient with OCPD think they have a problem?', '["Yes", "No, they think everyone else is doing it wrong (Ego-syntonic)", "Yes, they are distressed by it", "None"]', 1, 'They are rigid and stubborn. (MGH Pocket)'),
    (v_topic_id, '232: Body Dysmorphic Disorder (BDD) is characterized by:', '["Obsession with weight", "Preoccupation with one or more perceived defects or flaws in physical appearance that are unobservable or slight to others", "Fear of having a disease", "None"]', 1, 'Classified under OCD and Related Disorders. (DSM-5)'),
    (v_topic_id, '233: What repetitive behaviors are common in BDD?', '["Washing hands", "Mirror checking, excessive grooming, skin picking, or seeking reassurance", "Counting", "None"]', 1, 'Compulsions related to appearance. (First Aid)'),
    (v_topic_id, '234: What medical procedure do BDD patients frequently seek out?', '["Cardiac surgery", "Plastic surgery or dermatology treatments (which rarely satisfy them)", "Orthopedic surgery", "None"]', 1, 'A contraindication for cosmetic surgery. (Kaplan & Sadock)'),
    (v_topic_id, '235: Treatment for BDD?', '["Plastic surgery", "High-dose SSRIs and CBT", "Benzodiazepines", "Antipsychotics"]', 1, 'Similar treatment to OCD. (MGH Pocket)'),
    (v_topic_id, '236: Hoarding Disorder is characterized by:', '["Collecting stamps", "Persistent difficulty discarding or parting with possessions, regardless of their actual value", "Fear of being poor", "None"]', 1, 'Results in cluttered, unsafe living areas. (DSM-5)'),
    (v_topic_id, '237: How does Hoarding Disorder differ from OCD?', '["It is the same", "Hoarding egosyntonic, lacks intrusive obsessions, and SSRIs are generally LESS effective", "None", "None"]', 1, 'CBT specific for hoarding is best. (First Aid)'),
    (v_topic_id, '238: Trichotillomania is:', '["Fear of hair", "Recurrent pulling out of one''s hair, resulting in hair loss, despite repeated attempts to stop", "Fear of numbers", "None"]', 1, 'An OCD-related disorder. (DSM-5)'),
    (v_topic_id, '239: A physical complication of Trichotillomania if the patient swallows the hair?', '["Bezoar (trichobezoar) in the stomach, leading to bowel obstruction", "Lung fibrosis", "Kidney failure", "None"]', 0, 'Rapunzel syndrome. (Kaplan & Sadock)'),
    (v_topic_id, '240: Excoriation Disorder is:', '["Hair pulling", "Recurrent skin picking resulting in skin lesions", "Nail biting", "None"]', 1, 'Often face, arms, or hands. (DSM-5)'),
    (v_topic_id, '241: Treatment for Trichotillomania and Excoriation disorder?', '["SSRIs", "Habit Reversal Training (HRT) (a specific CBT)", "Benzos", "None"]', 1, 'Teaching a competing response (e.g., clenching fists when the urge to pick arises). (MGH Pocket)'),
    (v_topic_id, '242: Which medication is often used off-label for Trichotillomania to reduce urges?', '["Haloperidol", "N-acetylcysteine (NAC) (modulates glutamate)", "Lithium", "Propranolol"]', 1, 'Evidence shows benefit for impulse/picking behaviors. (First Aid)'),
    (v_topic_id, '243: A patient has a compulsion where they perform complex mental math to neutralize a bad thought. Is this a compulsion?', '["No, compulsions must be physical", "Yes, compulsions can be overt physical behaviors or covert MENTAL acts", "None", "None"]', 1, 'Mental compulsions are very common. (Kaplan & Sadock)'),
    (v_topic_id, '244: What is "Pure O" OCD?', '["Only compulsions", "Obsessions without obvious physical compulsions (though mental compulsions are usually present)", "None", "None"]', 1, 'Harder to treat with standard ERP. (MGH Pocket)'),
    (v_topic_id, '245: A postpartum mother has terrifying, intrusive thoughts of dropping her baby down the stairs. She hides all the baby carriers and refuses to carry the baby near stairs. She knows the thoughts are crazy. Diagnosis?', '["Postpartum Psychosis", "Postpartum OCD", "Postpartum Depression", "None"]', 1, 'Very common; important to reassure her she is not psychotic and won''t act on it. (First Aid)'),
    (v_topic_id, '246: Difference between Postpartum Psychosis and Postpartum OCD regarding risk to the child?', '["Both high risk", "Psychosis is high risk (delusions/commands); OCD is low risk (ego-dystonic, patient avoids harm)", "Both low risk", "None"]', 1, 'Crucial safety distinction. (Kaplan & Sadock)'),
    (v_topic_id, '247: What is "Primary Obsessional Slowness"?', '["Slow heart rate", "Patient takes hours to complete a simple task (like dressing) because they must do it perfectly or in a specific order", "None", "None"]', 1, 'A severe manifestation of OCD. (MGH Pocket)'),
    (v_topic_id, '248: A patient checks the stove 10 times, taking 5 minutes total per day, but is otherwise fine. Do they have OCD?', '["Yes", "No, does not meet the >1 hour/day or clinically significant distress criteria", "Yes, OCPD", "None"]', 1, 'Subclinical traits are normal. (First Aid)'),
    (v_topic_id, '249: Are men or women more affected by OCD?', '["Men", "Women", "Equally affected in adults (though boys have an earlier onset than girls)", "None"]', 2, 'One of the few anxiety-spectrum disorders without a strong female majority. (Kaplan & Sadock)'),
    (v_topic_id, '250: Does OCD have a genetic component?', '["No", "Yes, higher concordance in monozygotic twins and familial clustering", "Only in men", "None"]', 1, 'Strong genetic basis. (MGH Pocket)'),
    (v_topic_id, '251: What neurological infectious disease history is linked to OCD?', '["COVID-19", "Sydenham Chorea (Rheumatic fever) and Encephalitis Lethargica", "HIV", "None"]', 1, 'Basal ganglia damage. (First Aid)'),
    (v_topic_id, '252: Why are high doses of SSRIs required for OCD compared to MDD?', '["No one knows exactly, but the serotonergic requirement to alter the CSTC circuit is higher", "It is an error", "They aren''t", "None"]', 0, 'e.g., Fluoxetine up to 80mg/day. (Kaplan & Sadock)'),
    (v_topic_id, '253: How long does an adequate SSRI trial for OCD take?', '["2 weeks", "4 weeks", "8 to 12 weeks", "1 year"]', 2, 'Response is much slower than in depression. (MGH Pocket)'),
    (v_topic_id, '254: Fluvoxamine is an SSRI heavily used for OCD. What is its major drawback?', '["Liver failure", "Potent CYP450 inhibitor (1A2, 3A4) causing many drug-drug interactions", "Causes seizures", "None"]', 1, 'Must check interactions (e.g., with caffeine, clozapine). (First Aid)'),
    (v_topic_id, '255: BDD vs Anorexia Nervosa: A patient thinks they are hideous because their nose is too big.', '["Anorexia", "BDD (focuses on specific facial/body parts, not overall body fat/weight)", "Neither", "None"]', 1, 'If the ONLY concern is being "too fat," diagnose an eating disorder. (DSM-5)'),
    (v_topic_id, '256: Muscle Dysmorphia is a subtype of BDD characterized by:', '["Fear of muscles", "The belief that one''s body is too small or insufficiently muscular (mostly in males)", "Weakness", "None"]', 1, '"Megorexia" or reverse anorexia; leads to steroid abuse. (Kaplan & Sadock)'),
    (v_topic_id, '257: What is the insight specifier in BDD/OCD?', '["Good, Fair, Poor, or Absent/Delusional", "Only good", "None", "None"]', 0, 'If insight is completely absent, it can border on a somatic delusion. (MGH Pocket)'),
    (v_topic_id, '258: Does treating delusional BDD with antipsychotics work well?', '["Yes, first line", "No, even with absent insight, SSRIs remain the treatment of choice", "None", "None"]', 1, 'Antipsychotics alone fail. (First Aid)'),
    (v_topic_id, '259: True or False: Animal hoarding is a specific type of Hoarding Disorder.', '["True, often involves keeping dozens of animals without adequate care", "False", "None", "None"]', 0, 'High public health risk. (Kaplan & Sadock)'),
    (v_topic_id, '260: Does Hoarding Disorder incidence increase or decrease with age?', '["Decreases", "Increases (severity often worsens with each decade of life)", "Stays same", "None"]', 1, 'Often highly refractory in the elderly. (MGH Pocket)'),
    (v_topic_id, '261: In Trichotillomania, patients often feel what sensation before pulling?', '["Joy", "Increasing tension, followed by pleasure, gratification, or relief after pulling the hair", "Sadness", "None"]', 1, 'A tension-relief cycle. (First Aid)'),
    (v_topic_id, '262: Do patients with Excoriation Disorder pick their skin because of a delusion of parasites?', '["Yes", "No, if they pick due to a delusion, the diagnosis is Delusional Disorder (Somatic type)", "None", "None"]', 1, 'Must rule out psychosis or meth/cocaine abuse. (DSM-5)'),
    (v_topic_id, '263: OCD and Suicide: Risk?', '["Zero", "High risk, especially if comorbid with MDD", "None", "None"]', 1, 'The exhaustion of severe OCD drives suicidality. (Kaplan & Sadock)'),
    (v_topic_id, '264: A patient washes their hands 50 times a day until they bleed because they fear HIV. If they touch a doorknob, what happens to their anxiety?', '["Stays same", "Spikes immediately (Obsession)", "Drops", "None"]', 1, 'Trigger -> Obsession -> Anxiety spike. (First Aid)'),
    (v_topic_id, '265: When they wash their hands, what happens to the anxiety?', '["Spikes", "Drops temporarily (Compulsion provides negative reinforcement)", "Stays same", "None"]', 1, 'This cements the cycle. (MGH Pocket)'),
    (v_topic_id, '266: In ERP, if the patient touches the doorknob and is PREVENTED from washing, what happens?', '["They die", "Anxiety spikes very high, peaks, and eventually plateaus and slowly decreases (Habituation)", "None", "None"]', 1, 'The brain learns the anxiety will pass without the compulsion. (Kaplan & Sadock)'),
    (v_topic_id, '267: Which brain imaging scan shows hyperactivity in the caudate nucleus in OCD?', '["X-ray", "PET scan (showing increased glucose metabolism)", "Ultrasound", "None"]', 1, 'Classic research finding. (First Aid)'),
    (v_topic_id, '268: Are TCAs safe in overdose?', '["Yes", "No, lethal in overdose (cardiac arrhythmias/QRS widening, seizures, coma)", "Only Clomipramine", "None"]', 1, 'Why SSRIs are preferred. (MGH Pocket)'),
    (v_topic_id, '269: Clomipramine side effects include:', '["Weight loss", "Highly anticholinergic (dry mouth, constipation, blurry vision, urinary retention) and sedation", "None", "None"]', 1, 'Must counsel patients on these. (Kaplan & Sadock)'),
    (v_topic_id, '270: Clomipramine has a specific dose-dependent risk of:', '["Liver failure", "Seizures", "Renal failure", "None"]', 1, 'Max dose is strictly limited. (First Aid)'),
    (v_topic_id, '271: Y-BOCS is?', '["A virus", "Yale-Brown Obsessive Compulsive Scale (the standard rating scale for OCD severity)", "A therapy", "None"]', 1, 'Used to track treatment progress. (MGH Pocket)'),
    (v_topic_id, '272: Most common comorbidity with OCD?', '["Schizophrenia", "Major Depressive Disorder (up to 67% lifetime)", "Bipolar", "None"]', 1, 'Depression usually follows the onset of OCD. (Kaplan & Sadock)'),
    (v_topic_id, '273: Can stressful life events trigger the onset of OCD?', '["No", "Yes, frequently triggered by pregnancy, childbirth, or major trauma", "Only in men", "None"]', 1, 'Environmental triggers on a genetic substrate. (First Aid)'),
    (v_topic_id, '274: Is OCD more common in higher or lower socioeconomic classes?', '["Lower", "Equally distributed across all classes and cultures", "Higher", "None"]', 1, 'Universal disorder. (MGH Pocket)'),
    (v_topic_id, '275: Tourettic OCD?', '["A mix where compulsions are preceded by a physical ''tic-like'' urge rather than cognitive anxiety", "A myth", "None", "None"]', 0, 'Requires dopamine blocking agents + SSRIs. (Kaplan & Sadock)'),
    (v_topic_id, '276: Symbiosis of OCD and OCPD?', '["Never occur together", "Can be comorbid; OCPD traits may precede OCD", "None", "None"]', 1, 'Though distinct, they can overlap. (First Aid)'),
    (v_topic_id, '277: Koro (fear of genitals shrinking) resembles which disorder?', '["OCD / Somatic delusion", "Schizophrenia", "None", "None"]', 0, 'Culture-bound OCD spectrum. (MGH Pocket)'),
    (v_topic_id, '278: Compulsive hoarding vs collecting?', '["No difference", "Collecting is organized and targeted; Hoarding is disorganized, involves junk, and impairs living space", "None", "None"]', 1, 'Crucial difference. (Kaplan & Sadock)'),
    (v_topic_id, '279: Treatment for excoriation causing severe skin infections?', '["Ignore it", "Antibiotics for infection + HRT/SSRIs for the psychiatric disorder", "None", "None"]', 1, 'Requires multidisciplinary care. (First Aid)'),
    (v_topic_id, '280: Summary: First line for OCD?', '["CBT with ERP + High dose SSRI", "Low dose SSRI", "Benzo", "None"]', 0, 'The gold standard combination. (MGH Pocket)'),

    -- SECTION 5: Trauma- and Stressor-Related Disorders (281-350)
    (v_topic_id, '281: What is the defining Criterion A for PTSD?', '["Feeling sad", "Exposure to actual or threatened death, serious injury, or sexual violence (direct, witnessing, or learning it happened to close family)", "Watching the news", "None"]', 1, 'Must be a severe, life-threatening trauma. (DSM-5)'),
    (v_topic_id, '282: Does watching traumatic events on television or social media count as Criterion A for PTSD?', '["Yes", "No, unless it is work-related (e.g., first responders reviewing child abuse imagery)", "Only for children", "None"]', 1, 'General media exposure does not count. (First Aid)'),
    (v_topic_id, '283: PTSD symptoms are divided into 4 clusters. What are they?', '["Intrusion, Avoidance, Negative alterations in cognition/mood, and Arousal/reactivity", "Sadness, mania, psychosis, anxiety", "None", "None"]', 0, 'The core symptom categories. (DSM-5)'),
    (v_topic_id, '284: Intrusive symptoms in PTSD include:', '["Avoiding crowds", "Recurrent involuntary memories, distressing nightmares, and dissociative flashbacks", "Insomnia", "None"]', 1, 'The trauma intrudes into the present. (Kaplan & Sadock)'),
    (v_topic_id, '285: What is a flashback?', '["A bad memory", "A dissociative state where the individual feels or acts as if the traumatic event is recurring in the present", "A nightmare", "None"]', 1, 'Can lose touch with reality temporarily. (MGH Pocket)'),
    (v_topic_id, '286: Avoidance symptoms in PTSD include:', '["Avoiding sleep", "Efforts to avoid distressing memories/thoughts, or external reminders (people, places, conversations) associated with the trauma", "Avoiding work", "None"]', 1, 'e.g., a combat vet refusing to watch war movies. (First Aid)'),
    (v_topic_id, '287: Negative alterations in cognition/mood in PTSD include:', '["Mania", "Inability to remember key aspects of the trauma (dissociative amnesia), persistent negative beliefs, detachment from others", "Euphoria", "None"]', 1, 'Often resembles depression. (Kaplan & Sadock)'),
    (v_topic_id, '288: Arousal and reactivity symptoms in PTSD include:', '["Lethargy", "Irritability/anger outbursts, reckless behavior, hypervigilance, exaggerated startle response, and sleep disturbance", "Coma", "None"]', 1, 'The sympathetic nervous system remains "on." (MGH Pocket)'),
    (v_topic_id, '289: How long must symptoms be present to diagnose PTSD?', '["> 3 days", "> 1 week", "> 1 month", "> 6 months"]', 2, 'Crucial timeline distinction. (DSM-5)'),
    (v_topic_id, '290: If a patient has all the symptoms of PTSD following a trauma, but it has only been 2 weeks since the event, what is the diagnosis?', '["PTSD", "Acute Stress Disorder (ASD)", "Adjustment Disorder", "Normal"]', 1, 'ASD is diagnosed between 3 days and 1 month post-trauma. (First Aid)'),
    (v_topic_id, '291: Why is Acute Stress Disorder (ASD) a distinct diagnosis?', '["It requires different meds", "To identify individuals at high risk for developing PTSD and initiate early intervention", "It is milder", "None"]', 1, 'Up to 50% of ASD progresses to PTSD. (Kaplan & Sadock)'),
    (v_topic_id, '292: First-line pharmacological treatment for PTSD?', '["Benzodiazepines", "SSRIs (e.g., Sertraline, Paroxetine) or SNRIs (e.g., Venlafaxine)", "Antipsychotics", "Lithium"]', 1, 'Treats the core anxiety, mood, and arousal symptoms. (MGH Pocket)'),
    (v_topic_id, '293: Are Benzodiazepines recommended for PTSD?', '["Yes, first line", "No, they are relatively CONTRAINDICATED as they can worsen extinction learning, increase substance abuse risk, and do not treat core symptoms", "Only for sleep", "None"]', 1, 'VA guidelines strongly advise against benzos in PTSD. (First Aid)'),
    (v_topic_id, '294: Which medication is specifically used off-label to treat PTSD NIGHTMARES and sleep disturbance?', '["Zolpidem", "Prazosin (an Alpha-1 adrenergic antagonist)", "Haloperidol", "Melatonin"]', 1, 'Blocks the sympathetic surges during REM sleep that cause nightmares. (Kaplan & Sadock)'),
    (v_topic_id, '295: What must be monitored when starting Prazosin?', '["Liver enzymes", "Blood pressure (risk of orthostatic hypotension/syncope)", "WBC count", "None"]', 1, 'First-dose syncope is a known risk. (MGH Pocket)'),
    (v_topic_id, '296: First-line psychotherapies for PTSD? (Name two trauma-focused therapies)', '["Psychoanalysis and Hypnosis", "Prolonged Exposure (PE) and Cognitive Processing Therapy (CPT)", "Supportive therapy", "None"]', 1, 'Gold standard, evidence-based treatments. (First Aid)'),
    (v_topic_id, '297: EMDR (Eye Movement Desensitization and Reprocessing) is used for PTSD. What does it involve?', '["Medication", "Recalling traumatic images while simultaneously performing bilateral sensory stimulation (e.g., side-to-side eye movements)", "Shock therapy", "None"]', 1, 'The exposure element is what likely provides the benefit. (Kaplan & Sadock)'),
    (v_topic_id, '298: Adjustment Disorder is characterized by:', '["Psychosis", "Emotional or behavioral symptoms in response to an IDENTIFIABLE stressor (e.g., divorce, job loss) occurring within 3 months of the stressor", "Panic attacks", "None"]', 1, 'The stressor does NOT have to be life-threatening (unlike PTSD). (DSM-5)'),
    (v_topic_id, '299: To diagnose Adjustment Disorder, the symptoms must NOT persist for more than ____ after the stressor (or its consequences) has terminated.', '["1 month", "6 months", "1 year", "5 years"]', 1, 'If it lasts longer, diagnose GAD or MDD. (First Aid)'),
    (v_topic_id, '300: If a patient gets fired and develops severe sadness, anhedonia, suicidality, and vegetative symptoms meeting full criteria for MDD, what is the diagnosis?', '["Adjustment Disorder with depressed mood", "Major Depressive Disorder", "Normal bereavement", "None"]', 1, 'If full criteria for another major disorder are met, it trumps Adjustment Disorder. (MGH Pocket)'),
    (v_topic_id, '301: Normal Bereavement vs MDD?', '["Bereavement = sadness comes in waves (pangs of grief) intermixed with positive memories; self-esteem is preserved. MDD = persistent pervasive gloom, worthlessness.", "They are the same", "None", "None"]', 0, 'Can diagnose MDD during bereavement if criteria are met (DSM-5 removed the bereavement exclusion). (Kaplan & Sadock)'),
    (v_topic_id, '302: Prolonged Grief Disorder (new to DSM-5-TR) requires intense, disabling grief lasting at least how long after the death?', '["1 month", "6 months", "12 months (in adults)", "5 years"]', 2, 'Pathological mourning. (First Aid)'),
    (v_topic_id, '303: Reactive Attachment Disorder (RAD) in children is caused by:', '["Genetics", "Extreme insufficient care (social neglect, deprivation, frequent changes in caregivers) before age 5", "Head trauma", "None"]', 1, 'The child is emotionally withdrawn and rarely seeks or responds to comfort. (DSM-5)'),
    (v_topic_id, '304: Disinhibited Social Engagement Disorder (DSED) is caused by the same severe neglect as RAD, but presents as:', '["Violence", "Child actively approaches and interacts with unfamiliar adults with no reticence (overly familiar, wanders off without checking back)", "Autism", "None"]', 1, 'Indiscriminate sociability. (MGH Pocket)'),
    (v_topic_id, '305: Is "debriefing" (forcing victims to process trauma immediately after a disaster) recommended to prevent PTSD?', '["Yes, always", "No, routine psychological debriefing (e.g., CISD) is NOT recommended and may actually increase the risk of PTSD by interfering with natural coping", "Only for children", "None"]', 1, 'A major paradigm shift in trauma care. (Kaplan & Sadock)'),
    (v_topic_id, '306: Which brain region is hyperactive in PTSD?', '["Prefrontal cortex", "Amygdala (exaggerated fear response)", "Hippocampus", "None"]', 1, 'Similar to other anxiety disorders. (First Aid)'),
    (v_topic_id, '307: Which brain region is found to be SMALLER in volume in patients with chronic PTSD?', '["Cerebellum", "Hippocampus", "Amygdala", "None"]', 1, 'Glucocorticoid toxicity from chronic stress shrinks the hippocampus (memory consolidation issues). (MGH Pocket)'),
    (v_topic_id, '308: PTSD prevalence in the general population vs combat veterans?', '["~8% general; up to 30% in combat veterans", "Zero in general", "None", "None"]', 0, 'High risk in military and first responders. (Kaplan & Sadock)'),
    (v_topic_id, '309: What is the most common trauma leading to PTSD in women?', '["Car accidents", "Sexual assault/Rape", "Natural disasters", "Combat"]', 1, 'High probability of PTSD following sexual trauma. (First Aid)'),
    (v_topic_id, '310: What is the most common trauma leading to PTSD in men?', '["Sexual assault", "Combat exposure and witnessing death/injury", "Natural disasters", "None"]', 1, 'Epidemiological difference. (MGH Pocket)'),
    (v_topic_id, '311: A patient with PTSD turns to alcohol to sleep without nightmares. What is this called?', '["Cure", "Self-medication (very high comorbidity of SUD in PTSD)", "None", "None"]', 1, 'Must treat both concurrently. (Kaplan & Sadock)'),
    (v_topic_id, '312: What is the "Dissociative Subtype" of PTSD?', '["PTSD with amnesia", "PTSD accompanied by prominent symptoms of depersonalization or derealization", "PTSD with psychosis", "None"]', 1, 'A specific specifier in DSM-5. (DSM-5)'),
    (v_topic_id, '313: A patient was robbed at gunpoint 2 days ago. They are hypervigilant, having nightmares, and avoiding the street where it happened. Diagnosis?', '["PTSD", "Acute Stress Disorder", "Normal acute stress reaction (too early for ASD or PTSD diagnosis)", "None"]', 2, 'Must be at least 3 days for ASD. (First Aid)'),
    (v_topic_id, '314: Treatment for Adjustment Disorder?', '["Lifelong SSRIs", "Psychotherapy (supportive counseling, coping skills training) is the treatment of choice", "ECT", "None"]', 1, 'Meds only if targeted symptoms (e.g., insomnia) are severe. (MGH Pocket)'),
    (v_topic_id, '315: What is "Complex PTSD" (ICD-11, often referenced clinically)?', '["PTSD with math anxiety", "PTSD resulting from chronic, prolonged, repeated trauma (e.g., childhood abuse, captivity), leading to profound emotional dysregulation and personality changes", "None", "None"]', 1, 'Often overlaps with Borderline Personality Disorder. (Kaplan & Sadock)'),
    (v_topic_id, '316: Trauma-Focused CBT (TF-CBT) is specifically designed for:', '["Adult combat vets", "Children and adolescents who have experienced trauma", "Elderly", "None"]', 1, 'Includes a narrative component. (First Aid)'),
    (v_topic_id, '317: Can Second-Generation Antipsychotics (e.g., Quetiapine, Risperidone) be used in PTSD?', '["First line", "Used off-label as adjuncts for severe hyperarousal, paranoia, or treatment-resistant symptoms", "Never", "None"]', 1, 'Common in VA settings, but limited evidence. (MGH Pocket)'),
    (v_topic_id, '318: A patient is diagnosed with cancer and becomes intensely anxious, crying constantly, and missing work for a month. Diagnosis?', '["GAD", "Adjustment Disorder with anxiety", "PTSD", "None"]', 1, 'A severe medical illness can be the stressor for Adjustment Disorder. (Kaplan & Sadock)'),
    (v_topic_id, '319: Can a severe medical illness (e.g., waking up during surgery, anaphylaxis) trigger PTSD?', '["No", "Yes, if it qualifies as an actual/threatened death experience", "Only in kids", "None"]', 1, 'ICU trauma is a recognized cause of PTSD. (First Aid)'),
    (v_topic_id, '320: Is Mirtazapine useful for PTSD?', '["No", "Yes, off-label for sleep and appetite, and as a second-line antidepressant", "Only for nightmares", "None"]', 1, 'Good alternative if SSRIs fail. (MGH Pocket)'),
    (v_topic_id, '321: Somatic Symptom Disorder and PTSD?', '["High comorbidity; trauma often manifests physically (chronic pain)", "No relation", "None", "None"]', 0, 'The body keeps the score. (Kaplan & Sadock)'),
    (v_topic_id, '322: False Memory Syndrome?', '["A recognized DSM disorder", "A controversial concept where aggressive therapy/hypnosis inadvertently creates false memories of childhood trauma", "None", "None"]', 1, 'Why "repressed memory recovery" is highly controversial. (First Aid)'),
    (v_topic_id, '323: Dissociative Amnesia in PTSD?', '["Complete loss of identity", "Inability to recall an important aspect of the traumatic event (not due to head injury or drugs)", "None", "None"]', 1, 'A negative cognitive symptom. (MGH Pocket)'),
    (v_topic_id, '324: Exaggerated startle response?', '["Arousal symptom; jumping at loud noises like a car backfiring", "Intrusion symptom", "None", "None"]', 0, 'Hyperreactivity. (Kaplan & Sadock)'),
    (v_topic_id, '325: Hypervigilance?', '["Always sitting facing the door in a restaurant, constantly scanning for threats", "Avoidance", "None", "None"]', 0, 'Arousal symptom. (First Aid)'),
    (v_topic_id, '326: Emotional Numbing?', '["Feeling detached, estranged, unable to experience positive emotions (love, joy)", "Psychosis", "None", "None"]', 0, 'Negative mood symptom. (MGH Pocket)'),
    (v_topic_id, '327: "Survival Guilt"?', '["A delusion", "Guilt about surviving when others died, or guilt about actions taken to survive; common negative cognition in PTSD", "None", "None"]', 1, 'Targeted in Cognitive Processing Therapy. (Kaplan & Sadock)'),
    (v_topic_id, '328: Can a single traumatic event cause both ASD and then PTSD?', '["No", "Yes, ASD is the precursor; if it lasts >1 month, the diagnosis changes to PTSD", "None", "None"]', 1, 'A continuum. (First Aid)'),
    (v_topic_id, '329: Can PTSD onset be delayed?', '["No", "Yes, ''Delayed Expression'' specifier if full criteria are not met until at least 6 months after the event", "None", "None"]', 1, 'Common in veterans who decompensate after retiring. (MGH Pocket)'),
    (v_topic_id, '330: TBI (Traumatic Brain Injury) vs PTSD?', '["Identical", "Highly comorbid in combat; TBI has focal neuro deficits and headache/dizziness, while PTSD has intrusive memories", "None", "None"]', 1, 'Often occur together from blast injuries. (Kaplan & Sadock)'),
    (v_topic_id, '331: MDMA (Ecstasy) in PTSD?', '["FDA approved first line", "Currently in Phase 3 trials for MDMA-assisted psychotherapy for severe PTSD; shows massive promise by reducing amygdala fear response during therapy", "None", "None"]', 1, 'A breakthrough therapy designation. (First Aid)'),
    (v_topic_id, '332: Ketamine in PTSD?', '["Cures it", "Used off-label/research for rapid symptom reduction, similar to its use in TRD", "None", "None"]', 1, 'Emerging treatment. (MGH Pocket)'),
    (v_topic_id, '333: Stella Ganglion Block (SGB) in PTSD?', '["Heart surgery", "Injection of anesthetic into sympathetic nerve bundle in the neck; emerging treatment to ''reboot'' the autonomic nervous system", "None", "None"]', 1, 'Rapid reduction in hyperarousal. (Kaplan & Sadock)'),
    (v_topic_id, '334: Avoidance of conversations about the trauma?', '["Intrusion", "Avoidance symptom", "None", "None"]', 1, 'Active avoidance. (First Aid)'),
    (v_topic_id, '335: Risk factors for developing PTSD after trauma?', '["Male gender, high IQ", "Female gender, prior psychiatric history, severity of trauma, lack of social support post-trauma", "None", "None"]', 1, 'Social support is the #1 protective factor. (MGH Pocket)'),
    (v_topic_id, '336: Adjustment disorder duration?', '["Must resolve within 6 months of stressor termination", "Lifelong", "None", "None"]', 0, 'Temporary state. (Kaplan & Sadock)'),
    (v_topic_id, '337: Can moving to a new city cause Adjustment Disorder?', '["No", "Yes, if it causes clinically significant distress or impairment", "None", "None"]', 1, 'A common stressor. (First Aid)'),
    (v_topic_id, '338: Adjustment disorder with mixed anxiety and depressed mood?', '["A valid DSM-5 subtype", "Not allowed", "None", "None"]', 0, 'Very common. (MGH Pocket)'),
    (v_topic_id, '339: Adjustment disorder with disturbance of conduct?', '["A subtype where the patient acts out (e.g., vandalism, fighting, truancy)", "Psychosis", "None", "None"]', 0, 'More common in adolescents. (Kaplan & Sadock)'),
    (v_topic_id, '340: Can a terminal illness diagnosis cause Adjustment Disorder?', '["Yes, it is a classic stressor", "No", "None", "None"]', 0, 'Psychosocial oncology. (First Aid)'),
    (v_topic_id, '341: Acute Stress Disorder (ASD) requires how many symptoms from the 5 categories?', '["9 out of 14 possible symptoms", "All of them", "None", "None"]', 0, 'DSM-5 simplified ASD criteria. (MGH Pocket)'),
    (v_topic_id, '342: Can a panic attack happen in PTSD?', '["No", "Yes, triggered by trauma reminders", "None", "None"]', 1, 'Does not mean they have Panic Disorder. (Kaplan & Sadock)'),
    (v_topic_id, '343: Prazosin mechanism for nightmares?', '["Alpha-1 antagonist, blocks norepinephrine in the CNS during REM sleep", "SSRI", "None", "None"]', 0, 'Specific target. (First Aid)'),
    (v_topic_id, '344: First line med for PTSD?', '["SSRI/SNRI", "Benzo", "None", "None"]', 0, 'Paroxetine and Sertraline are FDA approved. (MGH Pocket)'),
    (v_topic_id, '345: Benzodiazepines in PTSD?', '["Avoid. May worsen recovery and cause addiction.", "First line", "None", "None"]', 0, 'Strong contraindication. (Kaplan & Sadock)'),
    (v_topic_id, '346: EMDR?', '["Eye movement desensitization and reprocessing", "A drug", "None", "None"]', 0, 'Psychotherapy. (First Aid)'),
    (v_topic_id, '347: Prolonged Exposure?', '["Requires patient to recount the trauma repeatedly until habituation occurs", "Avoidance", "None", "None"]', 0, 'Highly effective. (MGH Pocket)'),
    (v_topic_id, '348: Cognitive Processing Therapy (CPT)?', '["Focuses on challenging stuck points (e.g., ''It was my fault'') regarding the trauma", "Exposure", "None", "None"]', 0, 'Cognitive restructuring. (Kaplan & Sadock)'),
    (v_topic_id, '349: Normal bereavement duration?', '["Varies widely by culture, but intense symptoms usually lessen over 6-12 months", "1 week", "None", "None"]', 0, 'No strict time limit anymore. (First Aid)'),
    (v_topic_id, '350: Final Pearl: Amygdala vs Prefrontal Cortex in Anxiety?', '["Hyperactive amygdala (fear) + Hypoactive PFC (failure to inhibit)", "Hypoactive amygdala", "None", "None"]', 0, 'The neurobiological core of all anxiety disorders. (MediHelp Mastery)');

END $$;

COMMIT;
